#include <cstdint>

struct Book;          // provides best_bid/ask, sizes
struct ParamSet { int32_t edge_ticks; uint32_t quote_size; double max_inv; };
struct OrderIface { void place(bool buy, int32_t tick, uint32_t qty); void cancel(uint64_t id); };

class MarketMaker {
public:
    MarketMaker(OrderIface& oms) : oms_(oms) {}

    // Hot callback: tiny, branch-predictable, no alloc/lock.
    void onBookUpdate(const Book& b) {
        const ParamSet p = params_;                 // atomically-swapped snapshot
        int32_t mid = micro_mid(b);                  // cheap arithmetic
        int32_t bid = mid - p.edge_ticks - skew(inv_, p);
        int32_t ask = mid + p.edge_ticks - skew(inv_, p);
        requote(bid, ask, p.quote_size);             // diff vs current quotes
    }

    void onFill(bool buy, uint32_t qty, int32_t tick) {
        inv_ += buy ? (double)qty : -(double)qty;    // update inventory
        pnl_ += /* mark-to-market delta */ 0;
        // re-quote happens on next book update or immediately if needed
    }

    void onReject(uint64_t /*id*/) { /* re-evaluate / back off */ }
    void setParams(const ParamSet& p) { params_ = p; }   // from research thread
private:
    static int32_t micro_mid(const Book&);
    static int32_t skew(double inv, const ParamSet&);
    void requote(int32_t bid, int32_t ask, uint32_t size);
    OrderIface& oms_;
    ParamSet params_{};
    double inv_ = 0, pnl_ = 0;
};

// The strategy depends only on these interfaces, so backtest == paper == live.
struct EventSource { virtual bool next(Event&) = 0; };   // file | sim | live feed
struct OrderSink   { virtual void submit(const OrderAction&) = 0; }; // sim | paper | live

void run(EventSource& src, OrderSink& sink, MarketMaker& strat) {
    Event e;
    while (src.next(e)) {
        switch (e.kind) {
            case Event::BOOK: strat.onBookUpdate(*e.book); break;
            case Event::FILL: strat.onFill(e.buy, e.qty, e.tick); break;
            case Event::TIMER: /* strat.onTimer(e.ts) */ break;
        }
        // actions emitted by strat go to `sink` (sim matcher / paper / live gateway)
    }
}
